<template>  <div class="auth-page">    <div class="auth-card">      <h1>Відновлення пароля</h1>      <form @submit.prevent="submit">      <label>        Пошта        <input v-model.trim="email" type="email" placeholder="you@example.com" required />      </label>      <p v-if="message" class="ok">{{ message }}</p>      <p v-if="error" class="error">{{ error }}</p>      <button type="submit" class="primary">Надіслати</button>    </form>    <div class="links">      <RouterLink to="/login">Повернутися до входу</RouterLink>    </div>  </div>  </div></template><script setup>import { ref } from 'vue'import { useRouter } from 'vue-router'import { requestPasswordReset, authError } from '@/stores/auth'const router = useRouter()const email = ref('')const message = ref('')const error = authErrorasync function submit() {  message.value = ''  const res = await requestPasswordReset(email.value)  if (res.ok) {    message.value = res.message    if (res.token) {      router.push({ name: 'resetConfirm', query: { token: res.token } })    }  }}</script><style scoped>.auth-page {  min-height: 100vh;  background: #ffffff;  padding: 1rem;}.auth-card { max-width: 480px; margin: 8vh auto; padding:1.25rem; background:#fff; border:1px solid #e5e7eb; border-radius:10px; box-shadow:0 6px 24px rgba(0,0,0,.08); color: #111111 }label { display:block; margin: .75rem 0; font-weight: 600; }input { width:100%; padding:.6rem .7rem; border:1px solid #d1d5db; border-radius:8px; margin-top:.35rem; }button.primary { width:100%; margin-top:1rem; padding:.6rem .7rem; background:#6366f1; color:#fff; border:none; border-radius:8px; cursor:pointer; }button.primary:hover { background:#4f46e5; }.error { color:#b91c1c; margin-top:.5rem; }.ok { color:#059669; margin-top:.5rem; }</style>